import{c as A,Q as l,j as a,m as s}from"./chunks/framework.DOi4mjdC.js";const e="/assets/zh-cn_image_0000002444614021.Uk54XpLj.png",n="/assets/zh-cn_image_0000002411385581.CqWxF0jz.png",o="data:image/png;base64,",p="data:image/png;base64,",i="/assets/zh-cn_image_0000002444614873.DY-cD1cG.png",g="/assets/zh-cn_image_0000002411385293.DVSAzFeT.png",b=JSON.parse('{"title":"Matmul高阶API使能MDL模板","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能MDL模板","slug":"matmul高阶api使能mdl模板"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能MDL模板.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能MDL模板.md"}'),r={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能MDL模板.md"};function u(M,t,d,c,m,D){return l(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="matmul高阶api使能mdl模板" tabindex="-1">Matmul高阶API使能MDL模板 <a class="header-anchor" href="#matmul高阶api使能mdl模板" aria-label="Permalink to &quot;Matmul高阶API使能MDL模板&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在矩阵乘算子场景中，使用Matmul高阶API进行矩阵乘法计算，使能MDL模板对算子性能的提升效果。在MDL模板中，MTE2流水从Global Memory到A1/B1的数据搬运为一次性大包搬运，即一次MTE2能搬入多个Matmul计算的基本块，提升带宽利用率，使后续的MTE1流水尽可能复用A1/B1内基本块的缓存数据，减少MTE2的搬运次数。MDL模板的详细介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MatmulConfig</a>。</p><ul><li><p>MDL模板的适用场景</p><p>一般适用于MTE2循环搬运次数多的大shape场景，MDL模板在A1/B1中缓存多次计算需要的数据，避免MTE2频繁搬运。</p></li><li><p>MDL模板的约束条件</p><p>MDL模板的TCubeTiling结构体需要满足TCubeTiling约束条件和MDL模板补充约束条件，具体请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TCubeTiling%E7%BB%93%E6%9E%84%E4%BD%93.md" target="_blank" rel="noreferrer">TCubeTiling结构体</a>。</p></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;128, 1024&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;1024, 30720&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>当前案例使用的AI处理器共24个核，每个核中包含1个AIC核和2个AIV核。</p><p>Tiling参数如下：</p><ul><li><p>原始shape：M=128, N=30720, K=1024。</p></li><li><p>单核shape：按24个AIC核进行切分，singleCoreM=128，singleCoreN=1280，singleCoreK=1024。</p><p>对于B矩阵，沿着N轴进行切分，切分成24份的singleCoreN，单核上处理K * SingleCoreN大小的数据。对于A矩阵，M轴不进行切分即singleCoreM=M，单核上处理singleCoreM * K大小的数据。总共24个核参与计算。</p></li><li><p>基本块shape：baseM=128，baseN=256，baseK=64。</p></li><li><p>L1相关Tiling参数：stepM=1，stepN=1，stepKa=4，stepKb=4，depthA1=8，depthB1=8。</p></li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据，因为MDL模板主要优化MTE2搬运效率，重点分析MTE2的流水情况。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><ul><li><p>优化前的Profiling数据如下，Matmul默认为Norm模板。从C列的aic_time数据可以看出，多个核中最大算子执行耗时为83.68us。从C列的aic_time、L列的aic_mte2_time和M列的aic_mte2_ratio几组数据来看，MTE2平均耗时75.64us，耗时占比达到92%以上，因此需要优化MTE2流水的耗时。</p><p><img src="'+e+'" alt=""></p></li><li><p>优化前的流水图如下，MTE2分多次从Global Memory搬运基本块到A1/B1。由于输入的矩阵Shape较大，MTE2循环搬运的次数多，但每次只搬运1个基本块，导致带宽利用率低，整体的MTE2搬运耗时长。进而影响后续的MTE1和MMAD流水，导致流水之间同步等待时间偏长。如红框所示，第一个基本块（baseM*baseN）的计算需要调用16次MMAD指令（singleCoreK/baseK=16），从左侧的第1个MMAD指令调用开始，到右侧的第16个MMAD指令调用结束，期间耗时10.899us，其中大部分是流水同步等待耗时。</p><p><img src="'+n+'" alt=""></p></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>下图是默认的Norm模板的Matmul计算流水示意图，MTE2分多次从Global Memory搬运基本块到A1或B1，每次只搬运一个基本块。Norm模板的优势为启动开销小，可以提前启动MTE1流水；Norm模板的劣势为在大Shape场景，MTE2搬运次数多，搬运带宽利用率低，整体性能开销大。</p><p><strong>图 1</strong> 默认Norm模板流水示意图<br><img src="'+o+`" alt="" title="默认Norm模板流水示意图"></p><p>实现Norm模板的具体步骤如下：</p><ol><li><p>创建Matmul对象，使用默认的Norm模板参数CFG_NORM。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ASCENDC_CUBE_ONLY</span></span>
<span class="line"><span>#include &quot;lib/matmul_intf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, AType&gt;;</span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BType&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, CType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BiasType&gt;;</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_NORM&gt; matmulObj; // 使用CFG_NORM定义Matmul对象</span></span></code></pre></div></li></ol><p>下图是MDL模板的Matmul计算流水示意图，MTE2一次性从Global Memory搬运多个基本块到A1或B1，每次搬运stepM * stepKa个基本块到A1或搬运stepN * stepKb个基本块到B1。MDL模板的优势为MTE2一次性搬运多个基本块，带宽利用率高，后续的MTE1流水能尽可能复用A1或B1的缓存数据，MTE2重复搬运次数少。MDL模板的劣势为MTE2头开销时间较长，MTE1流水需要等待MTE2流水完成后才启动，MTE1启动时间晚。</p><p><strong>图 2</strong> MDL模板流水示意图<br><img src="`+p+`" alt="" title="MDL模板流水示意图"></p><p>Matmul API使能MDL模板的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_unitflag" target="_blank" rel="noreferrer">使能UnitFlag功能和MDL模板的Mamtul样例</a>。使能MDL模板的主要步骤如下：</p><ol><li><p>创建Matmul对象，使用默认的MDL模板参数CFG_MDL。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ASCENDC_CUBE_ONLY</span></span>
<span class="line"><span>#include &quot;lib/matmul_intf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, AType&gt;;</span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BType&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, CType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BiasType&gt;;</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_MDL&gt; matmulObj; // 使用CFG_MDL定义Matmul对象</span></span></code></pre></div></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li><p>优化后的Profiling数据如下，从C列的aic_time数据可以看出，多个核中最大算子执行耗时为53.4us，相较于优化前的83.68us有较大提升。从L列的aic_mte2_time数据可以看出，MTE2平均耗时下降较多，从优化前的75.64us降低至46.24us。</p><p><img src="`+i+'" alt=""></p></li><li><p>优化后的流水图如下，MDL模板相较于默认的Norm模板，MTE2可以一次性搬运多个基本块，整体的MTE2搬运次数减少了。同时因为MTE2一次搬运多个基本块到A1/B1，后续的MTE1流水能尽量复用A1/B1的缓存数据，减少了流水同步等待，提升了算子整体性能。如红框所示，第一个基本块（baseM*baseN）的计算需要调用16次MMAD指令（singleCoreK/baseK=16），从左侧的第1个MMAD指令调用开始，到右侧的第16个MMAD指令调用结束耗时约5.198us，较优化前的10.899us提升较大，其中流水同步等待时间大幅减少。</p><p><img src="'+g+'" alt=""></p></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>大Shape输入、MTE2搬运次数多，且MTE1流水等MTE2流水的同步等待耗时较长的场景下，可以使能MDL模板。通过实现MTE2从Global Memory一次性搬入多个基本块到A1或B1，使后续的MTE1流水能尽量复用A1/B1的缓存数据，减少MTE2的搬运次数，从而提升算子性能。</p>',27)])])}const C=A(r,[["render",u]]);export{b as __pageData,C as default};
